package android.content;import java.util.ArrayList;import java.util.List;public class ClipData {public static final class Item {private final CharSequence value;public Item(CharSequence value){this.value=value;}public CharSequence coerceToText(Context context){return value;}}private final List<Item> items=new ArrayList<>();public ClipData(Item item){items.add(item);}public static ClipData newPlainText(CharSequence label,CharSequence text){return new ClipData(new Item(text));}public void addItem(Item item){items.add(item);}public int getItemCount(){return items.size();}public Item getItemAt(int index){return items.get(index);}}
